<?php
namespace App\Notifications; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Broadcasting\ShouldBroadcast; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\BroadcastMessage; use Illuminate\Notifications\Notification;
class BusinessNotification extends Notification implements ShouldQueue, ShouldBroadcast { use Queueable; public function __construct(private readonly string $title, private readonly string $body) {} public function via(object $notifiable): array { return ['database','mail','broadcast']; } public function toArray(object $notifiable): array { return ['title'=>$this->title,'body'=>$this->body]; } public function toBroadcast(object $notifiable): BroadcastMessage { return new BroadcastMessage($this->toArray($notifiable)); } public function toMail(object $notifiable): \Illuminate\Notifications\Messages\MailMessage { return (new \Illuminate\Notifications\Messages\MailMessage)->subject($this->title)->line($this->body); } }
